entries[44476] = { ["name"] = "Alumeths Schädel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Kombiniert Alumeths Herz, Schädel, Szepter und Roben, um Alumeths Überreste zu erschaffen.\n\"Der Zustand des Schädels beginnt, sich zu verschlechtern, als Ihr ihn aus der Kiste entfernt.\"" }
entries[44477] = { ["name"] = "Alumeths Herz", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Kombiniert Alumeths Herz, Schädel, Szepter und Roben, um Alumeths Überreste zu erschaffen.\n\"Das Herz beginnt, schwach zu werden, als Ihr es aus der Kiste entfernt.\"" }
entries[44478] = { ["name"] = "Alumeths Szepter", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Kombiniert Alumeths Herz, Schädel, Szepter und Roben, um Alumeths Überreste zu erschaffen.\n\"Das Szepter beginnt, zu zerfallen, als Ihr es aus der Kiste entfernt.\"" }
entries[44479] = { ["name"] = "Alumeths Roben", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Kombiniert Alumeths Herz, Schädel, Szepter und Roben, um Alumeths Überreste zu erschaffen.\n\"Die Roben beginnen auszufransen, als Ihr sie aus der Kiste entfernt.\"" }
entries[44480] = { ["name"] = "Alumeths Überreste", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Erweckt Alumeth den Aufgestiegenen." }
entries[44481] = { ["name"] = "Schleifritzelspielzeuggorilla", ["text"] = "Benutzen: Entfesselt Euren inneren Affen! (20 Sek. Abklingzeit)\n\"Dschungelspringspaß für zu Hause!\"" }
