entries[44492] = { ["name"] = "Formel: Waffe - Berserker", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (440)\nBenutzen: Lehrt Euch, Nahkampfwaffen zu verzaubern, sodass die Angriffskraft auf Kosten verringerter Rüstung erhöht wird. Benötigt einen Gegenstand der Stufe 60 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass sie gelegentlich die Angriffskraft um 400 erhöht, die Rüstung wird während dieser Zeit jedoch verringert. Erfordert einen Gegenstand der Stufe 60 oder höher." }
entries[44493] = { ["name"] = "Rolle der Waffenverzauberung - Berserker", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass sie gelegentlich die Angriffskraft um 400 erhöht, die Rüstung wird während dieser Zeit jedoch verringert. Erfordert einen Gegenstand der Stufe 60 oder höher." }
entries[44494] = { ["name"] = "Formel: Waffe - Lebenswächter", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (425)\nBenutzen: Lehrt Euch, Nahkampfwaffen zu verzaubern, sodass der Träger manchmal bei ausgeführten Nahkampfangriffen geheilt wird. Benötigt einen Gegenstand der Stufe 60 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass sie ihren Träger bei einem erzielten Nahkampftreffer manchmal heilt. Erfordert einen Gegenstand der Stufe 60 oder höher." }
