entries[44498] = { ["name"] = "Formel: Armschiene - Überragende Zaubermacht", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (440)\nBenutzen: Lehrt Euch, Armschienen dauerhaft zu verzaubern, sodass die Zaubermacht um 30 erhöht wird. Erfordert einen Gegenstand der Stufe 60 oder höher.\nArmschienen dauerhaft verzaubern, sodass die Zaubermacht um 30 erhöht wird. Erfordert einen Gegenstand der Stufe 60 oder höher." }
entries[44499] = { ["name"] = "Geborgene Dunkeleisenteile", ["text"] = "Benötigt Ingenieurskunst (450)" }
entries[44500] = { ["name"] = "Elementiumveredelter Auspuff", ["text"] = "Benötigt Ingenieurskunst (450)\n\"Limitierte Auflage\"" }
entries[44501] = { ["name"] = "Goblinmaschinenkolben", ["text"] = "Benötigt Ingenieurskunst (450)\n\"Wird exklusiv von Roxi Rammrakete im K3 verkauft.\"" }
entries[44502] = { ["name"] = "Bauplan: Feuerstuhl", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (450)\nBenötigt Expedition der Horde\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Feuerstuhls.\nFeuerstuhl\nReittierBenötigt eine Horde-Rasse\nBenötigt Stufe 40\nBenötigt Reiten (150)\nBenutzen: Lehrt Euch, wie man diesen heißen Ofen fährt.\nBeschwört einen echt heißen Ofen oder parkt ihn. Dazwischen ist das Ding verdammt schnell.\nBenötigt Titanstahlbarren (12), Eine Hand voll Kobaltbolzen (40), Arktischer Pelz (2), Geborgene Dunkeleisenteile , Goblinmaschinenkolben (8), Elementiumveredelter Auspuff" }
entries[44503] = { ["name"] = "Bauplan: Chopper des Robogenieurs", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (450)\nBenötigt Vorposten der Allianz\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung einer Chopper des Robogenieurs.\nChopper des Robogenieurs\nReittierBenötigt eine Allianz-Rasse\nBenötigt Stufe 40\nBenötigt Reiten (150)\nBenutzen: Lehrt Euch, wie man diesen Chopper fährt.\nBeschwört einen echt fetten Chopper des Robogenieurs oder parkt ihn. Dazwischen ist das Ding verdammt schnell.\nBenötigt Titanstahlbarren (12), Eine Hand voll Kobaltbolzen (40), Arktischer Pelz (2), Geborgene Dunkeleisenteile , Goblinmaschinenkolben (8), Elementiumveredelter Auspuff" }
entries[44504] = { ["name"] = "Nesingwary 4000", ["text"] = "Wird beim Anlegen gebunden\nDistanz Schusswaffe\n254 - 472 Schaden Tempo 2.80\n(129.64 Schaden pro Sekunde)\n\nGelber Sockel\nSockelbonus: +8 Angriffskraft\n\nHaltbarkeit 90 / 90\nBenötigt Stufe 80\nAnlegen: Erhöht die kritische Trefferwertung um 21.\nAnlegen: Erhöht die Angriffskraft um 78." }
entries[44505] = { ["name"] = "Staubbringer", ["text"] = "Wird beim Anlegen gebunden\nEinhändig Dolch\n117 - 219 Schaden Tempo 1.40\n(120.00 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 78\nErhöht die Angriffskraft um 912 nur in Katzen-, Bären-, Terrorbären- und Mondkingestalt.\nTrefferchance: Überzieht den Feind mit 70 Feuerschaden.\n\"Klinge des Purpurroten Hausherren.\"" }
entries[44506] = { ["name"] = "Automat für Saronitpfeile", ["text"] = "Benutzen: Stellt 200 messerscharfe Saronitpfeile her.\n10 Aufladungen" }
entries[44507] = { ["name"] = "Ultrasichere Kugelmaschine", ["text"] = "Benutzen: Stellt 200 Mammutschneider her.\n10 Aufladungen\n\"Verursachte Unfälle durch dieses Gerät sind um fast 17% gesunken!\"" }
entries[44508] = { ["name"] = "Entdeckung!", ["text"] = "\"Entdeckt zufällig ein neues Alchemierezept.\"" }
entries[44509] = { ["name"] = "Muster: Reisetasche des Trappers", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (415)\nBenötigt Die Kalu'ak\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung einer Reisetasche des Trappers.\nReisetasche des Trappers\nWird beim Anlegen gebunden\n28 Platz Lederertasche\nBenötigt Schweres boreanisches Leder (8)" }
entries[44510] = { ["name"] = "Muster: Mammutbergbautasche", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (415)\nBenötigt Die Söhne Hodirs\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung einer Mammutbergbautasche.\nMammutbergbautasche\nWird beim Anlegen gebunden\n32 Platz Bergbautasche\nBenötigt Schweres boreanisches Leder (8)" }
entries[44511] = { ["name"] = "Muster: Drachenschuppenmunitionsbeutel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (415)\nBenötigt Die Kalu'ak\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung eines Drachenschuppenmunitionsbeutels.\nDrachenschuppenmunitionsbeutel\nWird beim Anlegen gebunden\n28 Platz Munitionsbeutel\nBenötigt Stufe 75\nBenötigt Eisige Drachenschuppe (20), Schweres boreanisches Leder (2)" }
entries[44512] = { ["name"] = "Muster: Verstärkter nerubischer Köcher", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (415)\nBenötigt Ritter der Schwarzen Klinge\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung eines verstärkten nerubischen Köchers.\nVerstärkter nerubischer Köcher\nWird beim Anlegen gebunden\n28 Platz Köcher\nBenötigt Stufe 75\nBenötigt Nerubisches Chitin (20), Schweres boreanisches Leder (2)" }
entries[44513] = { ["name"] = "Muster: Gesichtsmaske des Ausweiders", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (420)\nBenutzen: Lehrt Euch die Herstellung einer Gesichtsmaske des Ausweiders.\n\nGesichtsmaske des Ausweiders\nWird beim Anlegen gebunden\nKopf Leder\n428 Rüstung\n+69 Beweglichkeit\n+69 Ausdauer\nHaltbarkeit 60 / 60\nBenötigt Stufe 78\nAnlegen: Erhöht die kritische Trefferwertung um 46.\nAnlegen: Erhöht Eure Abhärtungswertung um 46.\nAnlegen: Erhöht die Angriffskraft um 92.\n\nSchlachtrüstung des Ausweiders (0/8)\nBindungen des Ausweiders\nBrustschutz des Ausweiders\nGesichtsmaske des Ausweiders\nStulpen des Ausweiders\nBeinschützer des Ausweiders\nSchulterpolster des Ausweiders\nTreter des Ausweiders\nTaillenschutz des Ausweiders\nBenötigt Schweres boreanisches Leder (12), Äonenluft" }
