entries[44559] = { ["name"] = "Muster: Pelzbesatz - Feuerwiderstand", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (400)\nBenutzen: Lehrt Euch die Herstellung von Pelzbesatz - Feuerwiderstand.\nArmschienen dauerhaft verzaubern, sodass sie den Feuerwiderstand um 70 erhöhen.\n\nEs können nur die Armschienen des Lederverarbeiters verzaubert werden und sie werden dadurch seelengebunden. Damit der Pelzbesatz wirkt, wird eine Lederverarbeitungsfertigkeit von mindestens 400 benötigt." }
