entries[44793] = { ["name"] = "Foliant der Verwandlung: Hase", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt Verwandlung: Hase.\nVerwandelt den Feind in einen harmlosen Hasen und zwingt ihn, 50 sec lang so herumzuhoppeln. Während der Hase herumwandert, kann er weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren." }
entries[44794] = { ["name"] = "Frühlingshasenpfote", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Frühlingshasen beschwören und freigeben." }
entries[44800] = { ["name"] = "Frühlingsrobe", ["text"] = "Wird beim Aufheben gebunden\nBrust\nBenutzen: Pflanzt eine Blume. (1 Min Abklingzeit)" }
entries[44802] = { ["name"] = "Eierkorb", ["text"] = "QuestgegenstandIn Schildhand geführt\nBenötigt Nobelgartenfest\nBenutzen: Erhöht das Tempo 10 sec lang um 60%. Funktioniert nur, wo während des Nobelgartenfestes bunt gefärbte Eier versteckt sind. (10 Sek. Abklingzeit)" }
entries[44803] = { ["name"] = "Frühlingsreif", ["text"] = "Wird beim Aufheben gebunden\nKopf\n2 Rüstung" }
entries[44804] = { ["name"] = "Indalamars Schwächungsverzauberung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Debuff the target increasing spell damage taken by 13%, reducing Fire, Frost, Shadow, Nature, and Arcane resistances by 165, and reducing armor by 25%." }
entries[44805] = { ["name"] = "Indalamars Testtotem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Summons a Stoneclaw Totem TEST." }
entries[44806] = { ["name"] = "Buntes Eierschalenstück", ["text"] = "Questgegenstand\nBenötigt Nobelgartenfest" }
entries[44807] = { ["name"] = "Indalars heilige Handgranate", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Segnet alle Ziele mit einer heiligen Machtinfusion oder verflucht sie mit dem Bann aller Schlachtzügler." }
entries[44808] = { ["name"] = "Magieerfüllte Rüstung der Horde", ["text"] = "Questgegenstand\n\"Die Essenz des Soldaten haftet an der Rüstung.\"" }
entries[44809] = { ["name"] = "Kräuterbeutel der Horde", ["text"] = "Questgegenstand\n\"Duftend und zerbrechlich\"" }
entries[44810] = { ["name"] = "Truthahnkäfig", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren plumpen Truthahn beschwören und freigeben." }
entries[44811] = { ["name"] = "Foliant der Verwandlung: Truthahn", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt 'Verwandlung: Truthahn'.\nVerwandelt den Feind in einen harmlosen Truthahn und zwingt ihn, 50 sec lang so herumzuwandern. Während der Truthahn herumwandert, kann er weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren." }
entries[44812] = { ["name"] = "Truthahnbüchse", ["text"] = "Wird beim Aufheben gebunden\nDauer: 7 tagen (Realzeit)\nBenutzen: Bedeckt das Ziel mit Truthahnfedern." }
entries[44815] = { ["name"] = "Rolle der Armschienenverzauberung - Großer Sturmangriff", ["text"] = "Benutzen: Armschienen dauerhaft so verzaubern, dass sie die Angriffskraft um 50 erhöhen. Erfordert einen Gegenstand der Stufe 60 oder höher." }
entries[44817] = { ["name"] = "Der Unruhestifter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verwandelt ein befreundetes Ziel in ein Schaf und zwingt es, 15 sec lang so herumzuwandern. Während das Schaf herumwandert, kann es weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren und ausschließlich in Dalaran." }
entries[44818] = { ["name"] = "Nobelgartenei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenötigt Nobelgartenfest\nBenutzen: Platziert ein bunt gefärbtes Ei. (1 Stunde Abklingzeit)" }
entries[44819] = { ["name"] = "Blizzardbärenbaby", ["text"] = "Accountgebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nRechtsklicken, um das Blizzardbärenbaby zu beschwören und freizugeben." }
entries[44820] = { ["name"] = "Rote Haustierleine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Eine rote Haustierleine aus Band." }
entries[44822] = { ["name"] = "Albinonatter", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Eure Schlange beschwören und freigeben." }
entries[44832] = { ["name"] = "Wasserpistole" }
entries[44833] = { ["name"] = "Leere Wasserpistole" }
entries[44834] = { ["name"] = "Wilder Truthahn", ["text"] = "Dauer: 7 tagen (Realzeit)\n\"Im Wald von Elwynn oder Tirisfal erjagt.\"" }
entries[44835] = { ["name"] = "Herbstliche Gewürze", ["text"] = "Dauer: 7 tagen (Realzeit)\n\"Von Händlern des Pilgerfreudenfests in den Hauptstädten verkauft.\"" }
entries[44836] = { ["name"] = "Kürbiskuchen", ["text"] = "Dauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Willenskraft und Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.", ["unresolvedValues"] = true }
entries[44837] = { ["name"] = "Gewürzbrotfüllung", ["text"] = "Dauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Trefferwertung und Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.", ["unresolvedValues"] = true }
entries[44838] = { ["name"] = "Langsam gerösteter Truthahn", ["text"] = "Dauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Angriffskraft um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 1.108) + 8] und Eure Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.", ["unresolvedValues"] = true }
entries[44839] = { ["name"] = "Kandierte Süßkartoffel", ["text"] = "Dauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Tempowertung und Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.", ["unresolvedValues"] = true }
entries[44840] = { ["name"] = "Moosbeerenchutney", ["text"] = "Dauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Zaubermacht um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.6616) + 4] und Eure Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.", ["unresolvedValues"] = true }
entries[44841] = { ["name"] = "Leckstein des kleinen Rehkitzes", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer kleines Rehkitzhaustier beschwören und freigeben." }
entries[44842] = { ["name"] = "Rotes Drachenfalkenreittier", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Reiten (300)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein sehr schnelles Reittier.\nBeschwört einen reitbaren roten Drachenfalken oder gibt ihn frei. Das ist ein sehr schnelles Reittier." }
entries[44843] = { ["name"] = "Blaues Drachenfalkenreittier", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Reiten (300)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein sehr schnelles Reittier.\nBeschwört einen reitbaren blauen Drachenfalken oder gibt ihn frei. Das ist ein sehr schnelles Reittier." }
entries[44844] = { ["name"] = "Truthahnrufer", ["text"] = "Wird beim Aufheben gebunden\nDauer: 7 tagen (Realzeit)\nBenutzen: Imitiert den Paarungsruf eines Truthahns. (2 Min Abklingzeit)" }
entries[44849] = { ["name"] = "Winzige grüne Stoffpuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Mit Rechtsklick eine winzige grüne Stoffpuppe platzieren. (30 Min Abklingzeit)" }
entries[44851] = { ["name"] = "Erntedankfestkochbuch", ["text"] = "Benötigt Kochkunst (1)\nBenutzen: Lehrt Euch, wie man verschiedene leckere Gerichte zubereitet.\nScharfe Wolfrippchen\nBenötigt Stufe 25\nBenutzen: Stellt im Verlauf von 27 sec 874.8 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 min lang 8 Ausdauer und Willenskraft.\nBenötigt Rotes Wolfsfleisch" }
entries[44853] = { ["name"] = "Honig", ["text"] = "Dauer: 7 tagen (Realzeit)\n\"Von Händlern des Pilgerfreudenfests in den Hauptstädten verkauft.\"" }
entries[44854] = { ["name"] = "Säuerliche Sumpfmoosbeeren", ["text"] = "Dauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 18 sec insgesamt 61.2 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Erhältlich vom Händler des Pilgerfreudenfests außerhalb von Eisenschmiede.\"" }
entries[44855] = { ["name"] = "Süßkartoffel von Teldrassil", ["text"] = "Dauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 18 sec insgesamt 61.2 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Erhältlich vom Händler des Pilgerfreudenfests in Darnassus.\"" }
entries[44856] = { ["name"] = "Truthahnstücke", ["text"] = "Dauer: 7 tagen (Realzeit)\nBenutzen: Fügt drei Truthahnteile zu einem ganzen Truthahn zusammen." }
entries[44857] = { ["name"] = "Schwarzes Drachenfalkenreittier", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Reiten (300)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein sehr schnelles Reittier.\nBeschwört einen reitbaren schwarzen Reitdrachenfalken oder gibt ihn frei. Das ist ein sehr schnelles Reittier." }
entries[44858] = { ["name"] = "Rezept: Moosbeerenchutney", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (160)\nBenutzen: Lehrt Euch, wie man Moosbeerenchutney zubereitet.\n\nMoosbeerenchutney\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Zaubermacht um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.6616) + 4] und Eure Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.\nBenötigt Säuerliche Sumpfmoosbeeren , Honig", ["unresolvedValues"] = true }
entries[44859] = { ["name"] = "Rezept: Kandierte Süßkartoffel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (220)\nBenutzen: Lehrt Euch, wie man kandierte Süßkartoffeln zubereitet.\n\nKandierte Süßkartoffel\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Tempowertung und Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.\nBenötigt Süßkartoffel von Teldrassil , Honig , Herbstliche Gewürze", ["unresolvedValues"] = true }
entries[44860] = { ["name"] = "Rezept: Gewürzbrotfüllung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (1)\nBenutzen: Lehrt Euch, wie man Gewürzbrotfüllung zubereitet.\n\nGewürzbrotfüllung\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Trefferwertung und Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.\nBenötigt Gewürzbrot , Herbstliche Gewürze", ["unresolvedValues"] = true }
entries[44861] = { ["name"] = "Rezept: Langsam gerösteter Truthahn", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (280)\nBenutzen: Lehrt Euch, wie man langsam gerösteten Truthahn zubereitet.\n\nLangsam gerösteter Truthahn\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Angriffskraft um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 1.108) + 8] und Eure Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.\nBenötigt Wilder Truthahn , Honig (2), Herbstliche Gewürze", ["unresolvedValues"] = true }
entries[44862] = { ["name"] = "Rezept: Kürbiskuchen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (100)\nBenutzen: Lehrt Euch, wie man Kürbiskuchen backt.\n\nKürbiskuchen\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Willenskraft und Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.\nBenötigt Reifer Elwynnkürbis , Honig", ["unresolvedValues"] = true }
entries[44866] = { ["name"] = "Treues Muli", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört Euer treues Muli, was Euch für eine Dauer von 3 min Zugriff auf Eure in der Bank gelagerten Gegenstände ermöglicht. (12 Std. Abklingzeit)" }
entries[44867] = { ["name"] = "Packmuli", ["text"] = "Einzigartig\nBenutzen: Beschwört ein Packmuli, was Euch für die Dauer von 3 min Zugriff auf Eure in der Bank gelagerten Gegenstände ermöglicht. Das Muli kann nur einmal beschworen werden. (1 Min Abklingzeit)" }
entries[44869] = { ["name"] = "Zorninsigne der Wildherzen", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Stufe 70\nAnlegen: Erhöht die Tempowertung um 71.\nAnlegen: Ihr verfallt in Raserei, nachdem Ihr eine Kreatur getötet habt, die Erfahrung gewährt. Eure kritische Trefferchance wird für die nächsten 10 Sekunden erhöht." }
entries[44870] = { ["name"] = "Orakeltalisman der Ablution", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Stufe 70\nAnlegen: Erhöht die kritische Trefferwertung um 71.\nAnlegen: Stellt Mana, Wut, Energie oder Runenmacht wieder her, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt." }
