entries[44890] = { ["name"] = "To'kinis Blasrohr", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Schießt auf den ausgewählten Frostleoparden oder Eispfotenbären, um diesen ruhig zu stellen und in einen leichten Schlaf zu versetzen. Kann nicht im Kampf eingesetzt werden oder wenn sich die Frostleoparden oder Eispfotenbären im Kampf befinden. (5 Sek. Abklingzeit)" }
entries[44891] = { ["name"] = "Titanengeschmiedete Vorherrschaftsstiefel", ["text"] = "Wird beim Aufheben gebunden\nFüße Leder\n388 Rüstung\n+76 Ausdauer\n+33 Intelligenz\n\nGelber Sockel\nSockelbonus: +4 Abhärtungswertung\n\nHaltbarkeit 60 / 60Klassen: Druide\nBenötigt Stufe 80\nAnlegen: Erhöht die Trefferwertung um 36.\nAnlegen: Erhöht Eure Abhärtungswertung um 44.\nAnlegen: Erhöht die Zaubermacht um 68." }
