entries[44912] = { ["name"] = "Fluss des Wissens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 80\nAnlegen: Erhöht Eure Abhärtungswertung um 84.\nAnlegen: Beim Wirken eines Zaubers besteht die Chance, dass Eure Zaubermacht 10 sec lang um 590 erhöht wird. (Procchance: 10%, 50s Abklingzeit)" }
entries[44914] = { ["name"] = "Amboss der Titanen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 80\nAnlegen: Erhöht Eure Abhärtungswertung um 84.\nAnlegen: Chance bei Nah- oder Fernkampfstreffer, Eure Angriffskraft 10 Sek. lang um 1.000 zu erhöhen. (Procchance: 10%, 50s Abklingzeit)" }
entries[44915] = { ["name"] = "Elunes Kerze", ["text"] = "Einzigartig\nBenutzen: Schießt ein Feuerwerk auf ein Ziel ab. (3 Sek. Abklingzeit)\n88 Aufladungen" }
entries[44916] = { ["name"] = "Muster: Festtagskleid", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (250)\nBenutzen: Lehrt Euch, wie man ein Festtagskleid näht.\nFesttagskleid\nBrust Stoff\n3 Rüstung\nHaltbarkeit 35 / 35\nBenötigt Runenstoffballen (4), Feuerblüte (2), Roter Farbstoff (2), Runenfaden" }
entries[44917] = { ["name"] = "Muster: Festtagsanzug", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (250)\nBenutzen: Lehrt Euch, wie man einen Festtagsanzug näht.\nFesttagsanzug\nBrust\nBenötigt Runenstoffballen (4), Feuerblüte (2), Roter Farbstoff (2), Runenfaden" }
entries[44918] = { ["name"] = "Bauplan: Zünder für Raketenbündel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (275)\nBenutzen: Lehrt Euch die Herstellung eines Zünders für Raketenbündel.\nZünder für Raketenbündel\nBenutzen: Auf dem Boden aufstellen, um Raketenbündel zu verschießen. Verschwindet nach 30 Minuten wieder.\nBenötigt Mithrilgehäuse , Goblinraketentreibstoff" }
entries[44919] = { ["name"] = "Bauplan: Zünder für Feuerwerk", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (225)\nBenutzen: Lehrt Euch die Herstellung eines Feuerwerkzünders.\nZünder für Feuerwerk\nBenutzen: Auf dem Boden aufstellen, um Feuerwerksraketen zu verschießen. Verschwindet nach 30 Minuten wieder.\nBenötigt Veredelter Mithrilzylinder , Goblinraketentreibstoff , Instabiler Auslöser , Mithrilgehäuse" }
entries[44920] = { ["name"] = "Glyphe 'Druckwelle'", ["text"] = "Geringe Glyphe\nKlassen: Magier\nBenötigt Stufe 70\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Manakosten Eures Zaubers 'Druckwelle' um 15%, Feinde werden jedoch nicht mehr zurückgestoßen." }
entries[44921] = { ["name"] = "Raptorei von Gundrak", ["text"] = "Questgegenstand\n\"Irgendwas bewegt sich da drin!\"" }
entries[44922] = { ["name"] = "Glyphe 'Taifun'", ["text"] = "Geringe Glyphe\nKlassen: Druide\nBenötigt Stufe 70\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Kosten Eures Zaubers 'Taifun' um 8% und erhöht seinen Radius um 10 Meter, Feinde werden jedoch nicht mehr zurückgestoßen." }
entries[44923] = { ["name"] = "Glyphe 'Gewitter'", ["text"] = "Geringe Glyphe\nKlassen: Schamane\nBenötigt Stufe 70\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Menge an Mana, die Ihr durch Euren Zauber 'Gewitter' erhaltet, um 2%, Feinde werden jedoch nicht mehr zurückgestoßen." }
entries[44924] = { ["name"] = "Arkanitreißer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Axt\n325 - 542 Schaden Tempo 3.80\n(114.08 Schaden pro Sekunde)\n+48 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 70\nAnlegen: Erhöht die kritische Trefferwertung um 24.\nAnlegen: Erhöht die Angriffskraft um 112.\nBenutzen: Zückt den Gesichtsschmelzer. (1 Min Abklingzeit)" }
entries[44926] = { ["name"] = "Titanstahldeflektor", ["text"] = "Wird beim Anlegen gebunden\nZweihändig Schwert\n507 - 761 Schaden Tempo 3.40\n(186.47 Schaden pro Sekunde)\n+89 Stärke\n+133 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 80\nAnlegen: Erhöht Eure Parierwertung um 90." }
entries[44928] = { ["name"] = "Glyphe 'Fokus'", ["text"] = "Erhebliche Glyphe\nKlassen: Druide\nBenötigt Stufe 70\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den von 'Sternenregen' verursachten Schaden um 10%, verringert gleichzeitig aber den Radius um 50%." }
