entries[44936] = { ["name"] = "Titanbeschlag", ["text"] = "Benötigt Stufe 70\nBenutzen: Bringt dauerhaft einen leichten Titanbeschlag an einem Schild an. Er erhöht den Blockwert um 81 und verringert die Dauer von Entwaffnungseffekten um 50%. Ist nicht mit ähnlichen Effekten stapelbar.\n\nDurch das Anbringen des Titanbeschlags wird der Gegenstand seelengebunden." }
entries[44937] = { ["name"] = "Pläne: Titanbeschlag", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (450)\nBenötigt Vorposten der Allianz\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung einer Titanpanzerung.\n\nTitanbeschlag\nBenötigt Stufe 70\nBenutzen: Bringt dauerhaft einen leichten Titanbeschlag an einem Schild an. Er erhöht den Blockwert um 81 und verringert die Dauer von Entwaffnungseffekten um 50%. Ist nicht mit ähnlichen Effekten stapelbar.\n\nDurch das Anbringen des Titanbeschlags wird der Gegenstand seelengebunden.\nBenötigt Titanbarren (4), Äonenschatten (4)" }
entries[44938] = { ["name"] = "Pläne: Titanbeschlag", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (450)\nBenötigt Expedition der Horde\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung einer Titanpanzerung.\n\nTitanbeschlag\nBenötigt Stufe 70\nBenutzen: Bringt dauerhaft einen leichten Titanbeschlag an einem Schild an. Er erhöht den Blockwert um 81 und verringert die Dauer von Entwaffnungseffekten um 50%. Ist nicht mit ähnlichen Effekten stapelbar.\n\nDurch das Anbringen des Titanbeschlags wird der Gegenstand seelengebunden.\nBenötigt Titanbarren (4), Äonenschatten (4)" }
entries[44939] = { ["name"] = "Geringes Fläschchen des Widerstands", ["text"] = "Benötigt Stufe 70\nBenutzen: Erhöht Euren Widerstand gegen alle Arten von Magie 1 hour lang um 50. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Der Effekt hält auch nach dem Tode an. (3 Sek. Abklingzeit)" }
entries[44940] = { ["name"] = "Mit Mais panniertes Würstchen", ["text"] = "Benötigt Stufe 75\nBenutzen: Stellt im Verlauf von 30 sec insgesamt 22500 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"... am Stiel!\"" }
entries[44941] = { ["name"] = "Frisch gepresstes Limonenwasser", ["text"] = "Benötigt Stufe 70\nBenutzen: Stellt im Verlauf von 30 sec insgesamt 12840 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[44943] = { ["name"] = "Eisiges Prisma", ["text"] = "Einzigartig\n\"Darin verstecken sich mehrere bezaubernde Edelsteine...\"\n<Zum Öffnen rechtsklicken>" }
entries[44944] = { ["name"] = "Formel: Armschiene - Erhebliche Ausdauer", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (450)\nBenutzen: Lehrt Euch, Armschienen dauerhaft zu verzaubern, sodass sie die Ausdauer um 40 erhöhen. Erfordert einen Gegenstand der Stufe 60 oder höher.\nArmschienen dauerhaft verzaubern, sodass die Ausdauer um 40 erhöht wird. Erfordert einen Gegenstand der Stufe 60 oder höher." }
entries[44945] = { ["name"] = "Formel: Waffe - Titanwache", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (450)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft so zu verzaubern, dass sie die Ausdauer um 50 erhöhen. Erfordert einen Gegenstand der Stufe 60 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass die Ausdauer um 50 erhöht wird. Erfordert einen Gegenstand der Stufe 60 oder höher." }
entries[44946] = { ["name"] = "Rolle der Waffenverzauberung - Titanwache", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass die Ausdauer um 50 erhöht wird. Erfordert einen Gegenstand der Stufe 60 oder höher." }
entries[44947] = { ["name"] = "Rolle der Armschienenverzauberung - Erhebliche Ausdauer", ["text"] = "Benutzen: Armschienen dauerhaft verzaubern, sodass die Ausdauer um 40 erhöht wird. Erfordert einen Gegenstand der Stufe 60 oder höher." }
entries[44948] = { ["name"] = "Titanstahlverteidiger", ["text"] = "Wird beim Anlegen gebunden\nZweihändig Axt\n507 - 761 Schaden Tempo 3.40\n(186.47 Schaden pro Sekunde)\n+89 Stärke\n+133 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 80\nAnlegen: Erhöht die Verteidigungswertung um 90." }
entries[44949] = { ["name"] = "Unzerstörbare Heilungsverstärker", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n1821 Rüstung\n+55 Ausdauer\n+60 Intelligenz\n\nMetasockel\nGelber Sockel\nSockelbonus: +9 Zaubermacht\n\nHaltbarkeit 100 / 100\nBenötigt Stufe 72\nBenötigt Ingenieurskunst (400)\nAnlegen: Erhöht die kritische Trefferwertung um 73.\nAnlegen: Erhöht die Zaubermacht um 87.\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen. (3 Sek. Abklingzeit)" }
entries[44950] = { ["name"] = "Raelorasz' Funken", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Zündet ein Signalfeuer an, das Keristrasza an Euren Standort beschwört. (2 Sek. Abklingzeit)" }
entries[44951] = { ["name"] = "Kiste voller Bomben", ["text"] = "\"Beinhaltet Saronitbomben. Jede Menge Saronitbomben.\"\n<Zum Öffnen rechtsklicken>" }
entries[44953] = { ["name"] = "Worgtatar", ["text"] = "Benötigt Stufe 70\nBenutzen: Stellt im Verlauf von 30 sec 22500 Gesundheit und 19200 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 hour lang 40 Trefferwertung und 40 Ausdauer." }
entries[44954] = { ["name"] = "Rezept: Worgtatar", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (400)\nBenutzen: Lehrt Euch, wie man Worgfleisch zu Worgtatar zerkleinert.\nDiese Delikatesse wird am Besten roh serviert und benötigt deshalb keine Kochstelle.\n\nWorgtatar\nBenötigt Stufe 70\nBenutzen: Stellt im Verlauf von 30 sec 22500 Gesundheit und 19200 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 hour lang 40 Trefferwertung und 40 Ausdauer.\nBenötigt Worgschenkel (2), Nordische Gewürze" }
entries[44955] = { ["name"] = "Glyphe 'Arkanschlag'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 64\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den Schaden Eures Stärkungszaubers 'Arkanschlag' um 3%." }
entries[44956] = { ["name"] = "Elementium - Das Handbuch für den Goblin", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Bergbau (300)\nBenutzen: Lehrt Euch, wie man Elementium verhüttet.\nElementiumbarren\nBenötigt Elementiumerz , Arkanitbarren (10), Feuerkern , Elementarfluxus (3)" }
entries[44957] = { ["name"] = "Große Inschrift des Gladiators", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\nBenutzen: Fügt einem Gegenstand, der sich an einem Schulterplatz befindet, dauerhaft 30 Ausdauer und 15 Abhärtungswertung hinzu.\n\nDurch diese Verzauberung wird der Gegenstand seelengebunden." }
entries[44958] = { ["name"] = "Astrales Öl", ["text"] = "Benutzen: Macht Euch 5 min lang transparent." }
entries[44963] = { ["name"] = "Irdene Beinrüstung", ["text"] = "Benötigt Stufe 80\nBenutzen: Eine Hose dauerhaft mit einer Irdenen Beinrüstung verstärken, sodass Eure Abhärtungswertung um 40 und die Ausdauer um 28 erhöht wird.\n\nDurch diese Verzauberung wird der Gegenstand seelengebunden." }
entries[44964] = { ["name"] = "Omars Kronjuwelen", ["text"] = "Heroisch\nBenutzen: Berechtigt Euer Ziel zur Großartigkeit.\n\"Azeroths größter Schatz\"" }
entries[44965] = { ["name"] = "Schössling von Teldrassil", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Schössling von Teldrassil beschwören und freigeben." }
entries[44970] = { ["name"] = "Welpe aus Dun Morogh", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Welpen aus Dun Morogh beschwören und freigeben." }
