entries[44977] = { ["name"] = "Rezept: Grubenratteneintopf", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (90)\nBenutzen: Lehrt Euch, wie man einen widerlichen Grubenratteneintopf zubereitet.\nGrubenratteneintopf\nBenötigt Stufe 10\nBenutzen: Stellt im Verlauf von 24 sec insgesamt 552 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nBenötigt Grubenratte" }
