entries[45000] = { ["name"] = "Winterhyazinthe", ["text"] = "Questgegenstand\nBenutzen: Bringt der Maid des Drak'Marsees 4 Winterhyazinthen als Geschenk dar. Sie können ihr nur innerhalb des Opferungszirkels von Drak'Mar angeboten werden. (3 Sek. Abklingzeit)" }
entries[45002] = { ["name"] = "Robopieps", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Robopieps beschwören und freigeben." }
