entries[45005] = { ["name"] = "Ewig brennende Glut", ["text"] = "Questgegenstand\nBenutzen: Nutzt die Macht der ewig brennenden Glut, um die Maid des Winterhauchsees vom Fluch des Eises zu befreien. (5 Sek. Abklingzeit)" }
entries[45006] = { ["name"] = "Jillians Tonikum der endlosen Wut", ["text"] = "Benötigt Stufe 75\nBenutzen: Erhöht die Angriffskraft 1 hour lang um 180. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[45007] = { ["name"] = "Jillians Tonikum des reinen Mojo", ["text"] = "Benötigt Stufe 75\nBenutzen: Erhöht 1 hour lang die Manaregeneration alle 5 Sek. um 45 Mana. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[45008] = { ["name"] = "Jillians Tonikum des Steinbluts", ["text"] = "Benötigt Stufe 75\nBenutzen: Erhöht 1 hour lang die maximale Gesundheit um 1300. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[45009] = { ["name"] = "Jillians Tonikum des Frostwyrm", ["text"] = "Benötigt Stufe 75\nBenutzen: Erhöht die Zaubermacht 1 hour lang um 125. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[45010] = { ["name"] = "Bergbau: Die Spitzhacke und Du", ["text"] = "Wird beim Anlegen gebunden\nIn Schildhand geführt\nBenötigt Stufe 70\nBenötigt Bergbau (1)" }
